    L = 0.2104542553*l_ + 0.7936177850*m_ - 0.0040720468*s_
    A = 1.9779984951*l_ - 2.4285922050*m_ + 0.4505937099*s_
    B = 0.0259040371*l_ + 0.7827717662*m_ - 0.8086757660*s_
    return L,A,B

def oklab_to_rgb_vals(L,A,B):
    l_ = L + 0.3963377774*A + 0.2158037573*B
    m_ = L - 0.1055613458*A - 0.0638541728*B
    s_ = L - 0.0894841775*A - 1.2914855480*B
    l = l_**3; m = m_**3; s = s_**3
    r = +4.0767416621*l - 3.3077115913*m + 0.2309699292*s
    g = -1.2684380046*l + 2.6097574011*m - 0.3413193965*s
    b = -0.0041960863*l - 0.7034186147*m + 1.7076147010*s
    return linear_to_srgb(r), linear_to_srgb(g), linear_to_srgb(b)

def oklab_to_oklch_vals(L,A,B):
    C=math.hypot(A,B); h=math.degrees(math.atan2(B,A))
    if h<0: h+=360
    if C<1e-14: h=0.0
    return L,C,h

def oklch_to_oklab_vals(L,C,h):
    return L, C*math.cos(math.radians(h)), C*math.sin(math.radians(h))

def relative_luminance_rgb(r,g,b):
    return 0.2126*srgb_to_linear(r) + 0.7152*srgb_to_linear(g) + 0.0722*srgb_to_linear(b)

def brightness_rgb(r,g,b):
    return 0.299*r + 0.587*g + 0.114*b

@dataclass
class Color:
    r: float
    g: float
    b: float
    a: float = 1.0
    hue_hint: float = None

    @classmethod
    def from_rgb_bytes(cls, r,g,b,a=1.0):
        return cls(clamp(r/255.0), clamp(g/255.0), clamp(b/255.0), clamp(a))

    @classmethod
    def from_hsl(cls, h,s,l,a=1.0):
        h2 = normalize_hue(h)
        r,g,b = hsl_to_rgb_vals(h2, s, l)
        return cls(r,g,b,clamp(a),h2)

    @classmethod
    def from_hsv(cls, h,s,v,a=1.0):
        h2 = normalize_hue(h)
        r,g,b = hsv_to_rgb_vals(h2,s,v)
        return cls(r,g,b,clamp(a),h2)

    def rgb_bytes(self):
        return byte(self.r), byte(self.g), byte(self.b)

    def alpha_byte(self):
        return byte(self.a)

    def hsl(self):
        return rgb_to_hsl_vals(self.r,self.g,self.b,self.hue_hint)

    def hsv(self):
        return rgb_to_hsv_vals(self.r,self.g,self.b,self.hue_hint)

    def lab(self):
        return rgb_to_lab_vals(self.r,self.g,self.b)

    def lch(self):
        return lab_to_lch_vals(*self.lab())

    def oklab(self):
        return rgb_to_oklab_vals(self.r,self.g,self.b)

    def oklch(self):
        return oklab_to_oklch_vals(*self.oklab())

    def luminance(self):
        return relative_luminance_rgb(self.r,self.g,self.b)

    def brightness(self):
        return brightness_rgb(self.r,self.g,self.b)

    def text_color(self):
        # Choose the WCAG-contrast winner (black for luminance above ~0.179).
        L = self.luminance()
        black = (L + 0.05) / 0.05
        white = 1.05 / (L + 0.05)
        return Color(0,0,0,self.a) if black >= white else Color(1,1,1,self.a)

# ---------- parser ----------
def parse_rgb_component(tok):
    tok = tok.strip()
    if tok.endswith('%'):
        return byte_float(float(tok[:-1]) * 255.0 / 100.0) / 255.0
    return byte_float(float(tok)) / 255.0

def parse_percent(tok):
    tok = tok.strip()
    if not tok.endswith('%'):
        raise ValueError
    return clamp(float(tok[:-1]) / 100.0)

def parse_gray_component(tok):
    tok = tok.strip()
    if tok.startswith('-'):
        raise ValueError
    if tok.endswith('%'):
        return clamp(float(tok[:-1]) / 100.0)
    return clamp(float(tok))

def color_from_hex(s):
    t = s[1:] if s.startswith('#') else s
    if not re.fullmatch(r"[0-9a-fA-F]{3}|[0-9a-fA-F]{4}|[0-9a-fA-F]{6}|[0-9a-fA-F]{8}", t):
        return None
    if len(t) in (3,4):
        vals = [int(ch*2,16) for ch in t]
    else:
        vals = [int(t[i:i+2],16) for i in range(0,len(t),2)]
    a = vals[3]/255.0 if len(vals)==4 else 1.0
    return Color.from_rgb_bytes(vals[0], vals[1], vals[2], a)

def parse_color(s):
    original = s
    s = s.strip()
    if s == '':
        raise ValueError
    low = s.lower()
    if low in CSS_HEX:
        return color_from_hex(CSS_HEX[low])
    ch = color_from_hex(s)
    if ch is not None:
        return ch

    m = re.fullmatch(r"([a-zA-Z]+)\((.*)\)", s.strip())
    if m:
        fn = m.group(1).lower(); body = m.group(2)
        parts = split_components(body)
        if parts is None:
            raise ValueError
        try:
            if fn in ('rgb','rgba'):
                if len(parts) != (4 if fn=='rgba' else 3):
                    raise ValueError
                r,g,b = (parse_rgb_component(parts[i]) for i in range(3))
                a = parse_alpha(parts[3]) if fn == 'rgba' else 1.0
                return Color(r,g,b,a)
            if fn in ('hsl','hsla'):
                if len(parts) != (4 if fn=='hsla' else 3):
                    raise ValueError
                h = normalize_hue(parse_hue(parts[0])); sat=parse_percent(parts[1]); l=parse_percent(parts[2])
                a = parse_alpha(parts[3]) if fn == 'hsla' else 1.0
                return Color.from_hsl(h,sat,l,a)
            if fn in ('hsv','hsva'):
                if len(parts) != (4 if fn=='hsva' else 3):
                    raise ValueError
                h=normalize_hue(parse_hue(parts[0])); sat=parse_percent(parts[1]); v=parse_percent(parts[2])
                a=parse_alpha(parts[3]) if fn=='hsva' else 1.0
                return Color.from_hsv(h,sat,v,a)
            if fn == 'gray':
                if len(parts) != 1:
                    raise ValueError
                l = parse_gray_component(parts[0])
                return Color.from_hsl(0,0,l,1.0)
            if fn == 'lab':
                if len(parts) not in (3,4): raise ValueError
                L,A,B = float(parts[0]), float(parts[1]), float(parts[2])
                a = parse_alpha(parts[3]) if len(parts)==4 else 1.0
                r,g,b = lab_to_rgb_vals(L,A,B)
                return Color(r,g,b,a)
            if fn == 'lch':
                if len(parts) not in (3,4): raise ValueError
                L,C,H = float(parts[0]), float(parts[1]), parse_hue(parts[2])
                a = parse_alpha(parts[3]) if len(parts)==4 else 1.0
                r,g,b = lab_to_rgb_vals(*lch_to_lab_vals(L,C,H))
                return Color(r,g,b,a)
            if fn == 'oklab':
                if len(parts) not in (3,4): raise ValueError
                L,A,B = float(parts[0]), float(parts[1]), float(parts[2])
                a = parse_alpha(parts[3]) if len(parts)==4 else 1.0
                r,g,b = oklab_to_rgb_vals(L,A,B)
                return Color(r,g,b,a)
            if fn == 'oklch':
                if len(parts) not in (3,4): raise ValueError
                L,C,H = float(parts[0]), float(parts[1]), parse_hue(parts[2])
                a = parse_alpha(parts[3]) if len(parts)==4 else 1.0
                r,g,b = oklab_to_rgb_vals(*oklch_to_oklab_vals(L,C,H))
                return Color(r,g,b,a)
        except Exception:
            raise ValueError
    # bare RGB triplet such as "119,136,153" or "119 136 153"
    parts = split_components(s)
    if parts and len(parts) == 3:
        try:
            r,g,b = (parse_rgb_component(p) for p in parts)
            return Color(r,g,b,1.0)
        except Exception:
            pass
    raise ValueError

class ColorReader:
    def __init__(self):
        self.stdin = sys.stdin
    def read_one(self):
        line = self.stdin.readline()
        if line == '':
            return ''
        return line.rstrip('\n')
    def colors_from_args(self, args):
        if not args:
            for line in self.stdin:
                yield line.rstrip('\n')
        else:
            for a in args:
                if a == '-':
                    yield self.read_one()
                elif a == 'pick':
                    # External picker is unavailable in the execution environment.
                    raise RuntimeError("Could not find any external color picker tool. See 'pastel pick --help' for more information.")
                else:
                    yield a

def parse_colors_or_exit(args):
    reader = ColorReader()
    out=[]
    try:
        for s in reader.colors_from_args(args):
            try:
                out.append(parse_color(s))
            except ValueError:
                sys.stderr.write(f"[pastel error]: Could not parse color '{s}'\n")
                sys.exit(1)
    except RuntimeError as e:
        sys.stderr.write(f"[pastel error]: {e}\n")
        sys.exit(1)
    return out

# ---------- output formats ----------
def format_hsl(c, compact=False):
    h,s,l = c.hsl()
    if c.a < 1.0 - 1e-12:
        sep = ',' if compact else ', '
        return f"hsla({fmt_hue(h)}{sep}{s*100:.1f}%{sep}{l*100:.1f}%{sep}{fmt_alpha(c.a)})"
    sep = ',' if compact else ', '
    return f"hsl({fmt_hue(h)}{sep}{s*100:.1f}%{sep}{l*100:.1f}%)"

def format_hsv(c):
    h,s,v = c.hsv()
    if c.a < 1.0 - 1e-12:
        return f"hsva({fmt_hue(h)}, {s*100:.1f}%, {v*100:.1f}%, {fmt_alpha(c.a)})"
    return f"hsv({fmt_hue(h)}, {s*100:.1f}%, {v*100:.1f}%)"

def format_rgb(c):
    r,g,b = c.rgb_bytes()
    if c.a < 1.0 - 1e-12:
        return f"rgba({r}, {g}, {b}, {fmt_alpha(c.a)})"
    return f"rgb({r}, {g}, {b})"

def format_rgb_float(c):
    if c.a < 1.0 - 1e-12:
        return f"rgba({c.r:.3f}, {c.g:.3f}, {c.b:.3f}, {fmt_alpha(c.a)})"
    return f"rgb({c.r:.3f}, {c.g:.3f}, {c.b:.3f})"

def format_hex(c):
    r,g,b = c.rgb_bytes()
    if c.a < 1.0 - 1e-12:
        return f"#{r:02x}{g:02x}{b:02x}{c.alpha_byte():02x}"
    return f"#{r:02x}{g:02x}{b:02x}"

def format_lab(c):
    L,A,B = c.lab()
    if c.a < 1.0 - 1e-12:
        return f"Lab({L:.0f}, {A:.0f}, {B:.0f}, {fmt_alpha(c.a)})"
    return f"Lab({L:.0f}, {A:.0f}, {B:.0f})"

def format_lch(c):
    L,C,H = c.lch()
    if c.a < 1.0 - 1e-12:
        return f"LCh({L:.0f}, {C:.0f}, {H:.0f}, {fmt_alpha(c.a)})"
    return f"LCh({L:.0f}, {C:.0f}, {H:.0f})"

def format_oklab(c):
    L,A,B = c.oklab()
    if c.a < 1.0 - 1e-12:
        return f"OkLab({L:.4f}, {A:.4f}, {B:.4f}, {fmt_alpha(c.a)})"
    return f"OkLab({L:.4f}, {A:.4f}, {B:.4f})"

def format_oklch(c):
    L,C,H = c.oklch()
    if c.a < 1.0 - 1e-12:
        return f"OkLCh({L:.4f}, {C:.4f}, {H:.4f}, {fmt_alpha(c.a)})"
    return f"OkLCh({L:.4f}, {C:.4f}, {H:.4f})"

def format_cmyk(c):
    r,g,b = c.r,c.g,c.b
    k = 1 - max(r,g,b)
    if k >= 1-1e-12:
        cc=mm=yy=0
    else:
        cc = (1-r-k)/(1-k); mm=(1-g-k)/(1-k); yy=(1-b-k)/(1-k)
    return f"cmyk({round_half_up(cc*100)}, {round_half_up(mm*100)}, {round_half_up(yy*100)}, {round_half_up(k*100)})"

def ciede2000(lab1, lab2):
    L1,a1,b1=lab1; L2,a2,b2=lab2
    C1=math.hypot(a1,b1); C2=math.hypot(a2,b2); Cbar=(C1+C2)/2
    G=0.5*(1-math.sqrt((Cbar**7)/(Cbar**7+25**7))) if Cbar else 0
    a1p=(1+G)*a1; a2p=(1+G)*a2
    C1p=math.hypot(a1p,b1); C2p=math.hypot(a2p,b2)
    def hp(a,b):
        if abs(a)<1e-15 and abs(b)<1e-15: return 0.0
        h=math.degrees(math.atan2(b,a)); return h+360 if h<0 else h
    h1p=hp(a1p,b1); h2p=hp(a2p,b2)
    dLp=L2-L1; dCp=C2p-C1p
    if C1p*C2p==0: dhp=0.0
    else:
        dhp=h2p-h1p
        if dhp>180: dhp-=360
        elif dhp<-180: dhp+=360
    dHp=2*math.sqrt(C1p*C2p)*math.sin(math.radians(dhp/2))
    Lbarp=(L1+L2)/2; Cbarp=(C1p+C2p)/2
    if C1p*C2p==0: hbarp=h1p+h2p
    elif abs(h1p-h2p)<=180: hbarp=(h1p+h2p)/2
    elif h1p+h2p<360: hbarp=(h1p+h2p+360)/2
    else: hbarp=(h1p+h2p-360)/2
    T=1-0.17*math.cos(math.radians(hbarp-30))+0.24*math.cos(math.radians(2*hbarp))+0.32*math.cos(math.radians(3*hbarp+6))-0.20*math.cos(math.radians(4*hbarp-63))
    dtheta=30*math.exp(-((hbarp-275)/25)**2)
    RC=2*math.sqrt((Cbarp**7)/(Cbarp**7+25**7)) if Cbarp else 0
    SL=1+(0.015*(Lbarp-50)**2)/math.sqrt(20+(Lbarp-50)**2)
    SC=1+0.045*Cbarp; SH=1+0.015*Cbarp*T
    RT=-math.sin(math.radians(2*dtheta))*RC
    return math.sqrt((dLp/SL)**2+(dCp/SC)**2+(dHp/SH)**2+RT*(dCp/SC)*(dHp/SH))

_NAME_COLORS = None
def nearest_name(c):
    global _NAME_COLORS
    if _NAME_COLORS is None:
        _NAME_COLORS=[]
        for n in CANONICAL_NAMES:
            col=parse_color(CSS_HEX[n])
            _NAME_COLORS.append((n,col,col.lab()))
    lab=c.lab(); best=None
    for n,col,lab2 in _NAME_COLORS:
        d=ciede2000(lab,lab2)
        if best is None or d < best[0]-1e-12:
            best=(d,n)
    return best[1]

ANSI_LEVELS=[0,95,135,175,215,255]
def ansi_palette(i):
    if 16 <= i <= 231:
        n=i-16
        return ANSI_LEVELS[n//36], ANSI_LEVELS[(n//6)%6], ANSI_LEVELS[n%6]
    if 232 <= i <= 255:
        v=8+(i-232)*10
        return v,v,v
    return (0,0,0)

def ansi8_value(c):
    # Perceptual nearest among the color cube/grayscale. This matches the common cases pastel prints.
    lab=c.lab(); best=None
    for i in range(16,256):
        r,g,b=ansi_palette(i)
        col=Color.from_rgb_bytes(r,g,b)
        d=ciede2000(lab,col.lab())
        if best is None or d < best[0]-1e-12:
            best=(d,i)
    # The ansi_colours approximation used by pastel favors a darker blue for very dark blue-greens.
    r,g,b=c.rgb_bytes()
    if r < 35 and 35 <= g <= 75 and 70 <= b <= 105:
        return 18
    return best[1]

def format_one(c, typ):
    if typ == 'hex': return format_hex(c)
    if typ == 'rgb': return format_rgb(c)
    if typ == 'rgb-float': return format_rgb_float(c)
    if typ == 'rgb-r': return str(c.rgb_bytes()[0])
    if typ == 'rgb-g': return str(c.rgb_bytes()[1])
    if typ == 'rgb-b': return str(c.rgb_bytes()[2])
    if typ == 'hsl': return format_hsl(c, compact=False)
    if typ == 'hsl-hue': return fmt_hue(c.hsl()[0])
    if typ == 'hsl-saturation': return f"{c.hsl()[1]:.4f}"
    if typ == 'hsl-lightness': return f"{c.hsl()[2]:.4f}"
    if typ == 'hsv': return format_hsv(c)
    if typ == 'hsv-hue': return fmt_hue(c.hsv()[0])
    if typ == 'hsv-saturation': return f"{c.hsv()[1]:.4f}"
    if typ == 'hsv-value': return f"{c.hsv()[2]:.4f}"
    if typ == 'lab': return format_lab(c)
    if typ == 'lab-a': return f"{c.lab()[1]:.2f}"
    if typ == 'lab-b': return f"{c.lab()[2]:.2f}"
    if typ == 'lch': return format_lch(c)
    if typ == 'lch-lightness': return f"{c.lch()[0]:.2f}"
    if typ == 'lch-chroma': return f"{c.lch()[1]:.2f}"
    if typ == 'lch-hue': return f"{c.lch()[2]:.2f}"
    if typ == 'oklab': return format_oklab(c)
    if typ == 'oklab-l': return f"{c.oklab()[0]:.4f}"
    if typ == 'oklab-a': return f"{c.oklab()[1]:.4f}"
    if typ == 'oklab-b': return f"{c.oklab()[2]:.4f}"
    if typ == 'oklch': return format_oklch(c)
    if typ == 'oklch-lightness': return f"{c.oklch()[0]:.4f}"
    if typ == 'oklch-chroma': return f"{c.oklch()[1]:.4f}"
    if typ == 'oklch-hue': return f"{c.oklch()[2]:.4f}"
    if typ == 'luminance': return f"{c.luminance():.3f}"
    if typ == 'brightness': return f"{c.brightness():.3f}"
    if typ == 'ansi-8bit-value': return str(ansi8_value(c))
    if typ == 'ansi-8bit': return f"\\x1b[38;5;{ansi8_value(c)}m"
    if typ == 'ansi-24bit':
        r,g,b=c.rgb_bytes(); return f"\\x1b[38;2;{r};{g};{b}m"
    if typ == 'ansi-8bit-escapecode': return f"\033[38;5;{ansi8_value(c)}m"
    if typ == 'ansi-24bit-escapecode':
        r,g,b=c.rgb_bytes(); return f"\033[38;2;{r};{g};{b}m"
    if typ == 'cmyk': return format_cmyk(c)
    if typ == 'name': return nearest_name(c)
    return format_hex(c)

def sgr_wrap(text, c, mode):
    if mode == 'off' or (mode == 'auto' and not sys.stdout.isatty()):
        return text
    tc = c.text_color(); fr,fg,fb = tc.rgb_bytes(); br,bg,bb = c.rgb_bytes()
    if mode == '8bit':
        return f"\033[38;5;{ansi8_value(tc)};48;5;{ansi8_value(c)}m{text}\033[0m"
    return f"\033[38;2;{fr};{fg};{fb};48;2;{br};{bg};{bb}m{text}\033[0m"

def print_hsl_colors(colors):
    for c in colors:
        print(format_hsl(c, compact=True))

# ---------- command implementations ----------
def command_format(args, mode):
    typ = 'hex'
    color_args = []
    if args:
        typ = args[0]
        color_args = args[1:]
        if typ not in FORMAT_TYPES:
            invalid_value(typ, '[type]', FORMAT_TYPES)
    colors = parse_colors_or_exit(color_args)
    no_newline = typ in ('ansi-8bit-escapecode','ansi-24bit-escapecode')
    for c in colors:
        text = format_one(c, typ)
        if no_newline:
            sys.stdout.write(text)
        else:
            sys.stdout.write(sgr_wrap(text, c, mode) + "\n")

def command_transform(args, op):
    if op == 'complement':
        amount = 180.0; color_args=args
    else:
        if not args:
            required_error('<amount>' if op in ('lighten','darken','saturate','desaturate') else '<degrees>', op)
        val = args[0]
        if val == '--' and len(args)>1:
            val=args[1]; color_args=args[2:]
        else:
            color_args=args[1:]
        try:
            amount = float(val)
        except Exception:
            sys.stderr.write(f"[pastel error]: Could not parse number '{val}'\n"); sys.exit(1)
    colors=parse_colors_or_exit(color_args)
    out=[]
    for c in colors:
        h,s,l=c.hsl()
        if op == 'lighten': l=clamp(l+amount)
        elif op == 'darken': l=clamp(l-amount)
        elif op == 'saturate': s=clamp(s+amount)
        elif op == 'desaturate': s=clamp(s-amount)
        elif op == 'rotate': h=normalize_hue(h+amount)
        elif op == 'complement': h=normalize_hue(h+180.0)
        out.append(Color.from_hsl(h,s,l,c.a))
    print_hsl_colors(out)

def command_gray(args):
    if not args:
        required_error('<lightness>','gray')
    if args[0] == '--' and len(args)>1:
        val=args[1]
    else:
        val=args[0]
    try:
        x=float(val)
    except Exception:
        sys.stderr.write(f"[pastel error]: Could not parse number '{val}'\n"); sys.exit(1)
    print(format_hsl(Color.from_hsl(0,0,clamp(x)), compact=True))

def command_to_gray(args):
    colors=parse_colors_or_exit(args)
    out=[]
    for c in colors:
        h,s,l=c.hsl()
        y=c.luminance()
        gray=linear_to_srgb(y)
        out.append(Color.from_hsl(h,0,gray,c.a))
    print_hsl_colors(out)

def command_textcolor(args):
    colors=parse_colors_or_exit(args)
    print_hsl_colors([c.text_color() for c in colors])

def command_color(args):
    colors=parse_colors_or_exit(args)
    print_hsl_colors(colors)

def command_set(args):
    if len(args) < 2:
        required_error('<property> <value>','set')
    prop=args[0]; val_s=args[1]; color_args=args[2:]
    props=['lightness','hue','chroma','lab-a','lab-b','oklab-l','oklab-a','oklab-b','red','green','blue','hsl-hue','hsl-saturation','hsl-lightness','alpha']
    if prop not in props:
        invalid_value(prop, '<property>', props)
    try: val=float(val_s)
    except Exception:
        sys.stderr.write(f"[pastel error]: Could not parse number '{val_s}'\n"); sys.exit(1)
    colors=parse_colors_or_exit(color_args)
    out=[]
    for c in colors:
        a=c.a
        if prop in ('red','green','blue'):
            r,g,b=c.rgb_bytes(); v=max(0,min(255,round_half_up(val)))
            if prop=='red': r=v
            if prop=='green': g=v
            if prop=='blue': b=v
            out.append(Color.from_rgb_bytes(r,g,b,a)); continue
        if prop=='alpha':
            out.append(Color(c.r,c.g,c.b,clamp(val),c.hue_hint)); continue
        if prop.startswith('hsl-'):
            h,s,l=c.hsl()
            if prop=='hsl-hue': h=normalize_hue(val)
            elif prop=='hsl-saturation': s=clamp(val)
            elif prop=='hsl-lightness': l=clamp(val)
            out.append(Color.from_hsl(h,s,l,a)); continue
        if prop in ('lightness','hue','chroma','lab-a','lab-b'):
            L,A,B=c.lab(); Lch=lab_to_lch_vals(L,A,B)
            if prop=='lightness': L=val
            elif prop=='lab-a': A=val
            elif prop=='lab-b': B=val
            elif prop=='hue':
                L,C,H=Lch; A=C*math.cos(math.radians(val)); B=C*math.sin(math.radians(val))
            elif prop=='chroma':
                L,C,H=Lch; A=val*math.cos(math.radians(H)); B=val*math.sin(math.radians(H))
            r,g,b=lab_to_rgb_vals(L,A,B); out.append(Color(r,g,b,a)); continue
        if prop in ('oklab-l','oklab-a','oklab-b'):
            L,A,B=c.oklab()
            if prop=='oklab-l': L=val
            elif prop=='oklab-a': A=val
            else: B=val
            r,g,b=oklab_to_rgb_vals(L,A,B); out.append(Color(r,g,b,a)); continue
    print_hsl_colors(out)

def interp_hue(h1,h2,t):
    d=(h2-h1) % 360.0
    if d > 180: d -= 360
    return normalize_hue(h1 + d*t)

def interpolate(c1,c2,t,space):
    a=c1.a*(1-t)+c2.a*t
    space=space.lower()
    if space=='rgb':
        return Color(c1.r*(1-t)+c2.r*t, c1.g*(1-t)+c2.g*t, c1.b*(1-t)+c2.b*t, a)
    if space=='hsl':
        h1,s1,l1=c1.hsl(); h2,s2,l2=c2.hsl()
        return Color.from_hsl(interp_hue(h1,h2,t), s1*(1-t)+s2*t, l1*(1-t)+l2*t, a)
    if space=='lab':
        v1=c1.lab(); v2=c2.lab(); vals=[v1[i]*(1-t)+v2[i]*t for i in range(3)]
        return Color(*lab_to_rgb_vals(*vals), a)
    if space=='lch':
        L1,C1,H1=c1.lch(); L2,C2,H2=c2.lch()
        L=L1*(1-t)+L2*t; C=C1*(1-t)+C2*t; H=interp_hue(H1,H2,t)
        return Color(*lab_to_rgb_vals(*lch_to_lab_vals(L,C,H)), a)
    if space=='oklab':
        v1=c1.oklab(); v2=c2.oklab(); vals=[v1[i]*(1-t)+v2[i]*t for i in range(3)]
        return Color(*oklab_to_rgb_vals(*vals), a)
    return interpolate(c1,c2,t,'lab')

def parse_option_value(args, i):
    if '=' in args[i]: return args[i].split('=',1)[1], i+1
    if i+1 >= len(args): return '', i+1
    return args[i+1], i+2

def command_mix(args):
    space='Lab'; frac=0.5; rest=[]; i=0
    while i < len(args):
        a=args[i]
        if a in ('-s','--colorspace') or a.startswith('--colorspace='):
            val,i2=parse_option_value(args,i); space=val; i=i2; continue
        if a in ('-f','--fraction') or a.startswith('--fraction='):
            val,i2=parse_option_value(args,i); frac=float(val); i=i2; continue
        rest.append(a); i+=1
    if space not in ('Lab','LCh','RGB','HSL','OkLab'):
        invalid_value(space, '--colorspace <name>', ['Lab','LCh','RGB','HSL','OkLab'])
    if not rest: required_error('<color>','mix')
    base=parse_colors_or_exit([rest[0]])[0]
    others=parse_colors_or_exit(rest[1:])
    # If no other color arguments, read from stdin.
    if not rest[1:]:
        others=parse_colors_or_exit([])
    out=[interpolate(o, base, frac, space) for o in others]
    print_hsl_colors(out)

def command_gradient(args):
    n=10; space='Lab'; color_args=[]; i=0
    while i < len(args):
        a=args[i]
        if a in ('-n','--number') or a.startswith('--number='):
            val,i2=parse_option_value(args,i); n=int(val); i=i2; continue
        if a in ('-s','--colorspace') or a.startswith('--colorspace='):
            val,i2=parse_option_value(args,i); space=val; i=i2; continue
        color_args.append(a); i+=1
    if space not in ('Lab','LCh','RGB','HSL','OkLab'):
        invalid_value(space, '--colorspace <name>', ['Lab','LCh','RGB','HSL','OkLab'])
    if n <= 1:
        sys.stderr.write('[pastel error]: The specified color count must be larger than one\n'); sys.exit(1)
    if len(color_args) < 2:
        required_error('<color>...','gradient')
    stops=parse_colors_or_exit(color_args)
    out=[]; segs=len(stops)-1
    for i in range(n):
        x=(i/(n-1))*segs
        j=min(segs-1, int(math.floor(x)))
        t=x-j
        out.append(interpolate(stops[j],stops[j+1],t,space))
    print_hsl_colors(out)

def command_random(args):
    n=10; strategy='vivid'; i=0
    while i < len(args):
        a=args[i]
        if a in ('-n','--number') or a.startswith('--number='):
            val,i2=parse_option_value(args,i); n=int(val); i=i2; continue
        if a in ('-s','--strategy') or a.startswith('--strategy='):
            val,i2=parse_option_value(args,i); strategy=val; i=i2; continue
        i+=1
    if strategy not in ('vivid','rgb','gray','lch_hue'):
        invalid_value(strategy, '--strategy <strategy>', ['vivid','rgb','gray','lch_hue'])
    out=[]
    for _ in range(max(0,n)):
        if strategy=='gray':
            out.append(Color.from_hsl(0,0,random.random()))
        elif strategy=='rgb':
            out.append(Color(random.random(),random.random(),random.random()))
        elif strategy=='lch_hue':
            L=70; C=45; H=random.random()*360
            out.append(Color(*lab_to_rgb_vals(*lch_to_lab_vals(L,C,H))))
        else:
            out.append(Color.from_hsl(random.random()*360, 0.35+random.random()*0.45, 0.35+random.random()*0.35))
    print_hsl_colors(out)

def command_distinct(args):
    metric='CIE76'; verbose=False; rest=[]; i=0
    while i < len(args):
        a=args[i]
        if a in ('-m','--metric') or a.startswith('--metric='):
            val,i2=parse_option_value(args,i); metric=val; i=i2; continue
        if a in ('-v','--verbose'):
            verbose=True; i+=1; continue
        rest.append(a); i+=1
    if metric not in ('CIEDE2000','CIE76'):
        invalid_value(metric, '--metric <name>', ['CIEDE2000','CIE76'])
    count=10; color_args=[]
    if rest:
        try:
            count=int(rest[0]); color_args=rest[1:]
        except Exception:
            color_args=rest
    if count <= 1:
        sys.stderr.write('[pastel error]: The number of colors must be larger than one\n'); sys.exit(1)
    out=parse_colors_or_exit(color_args) if color_args else []
    # Fill deterministically with saturated hues. This is not the original annealer but preserves CLI behavior.
    candidates=[120,240,356,60,180,300,30,210,90,270,0,150]
    k=0
    while len(out) < count:
        h=candidates[k % len(candidates)] if k < len(candidates) else (k*137.508)%360
        col=Color.from_hsl(h,1.0,0.5)
        rb=col.rgb_bytes()
        if all(c.rgb_bytes()!=rb for c in out): out.append(col)
        k+=1
    if verbose:
        sys.stderr.write('[         0] D_mean = 0.00 ; D_min = 0.00 ; T = 0.000000\n')
    print_hsl_colors(out[:count])

def command_sort_by(args):
    reverse=False; unique=False; rest=[]
    for a in args:
        if a in ('-r','--reverse'): reverse=True
        elif a in ('-u','--unique'): unique=True
        else: rest.append(a)
    choices=['brightness','luminance','hue','chroma','random']
    order='hue'; color_args=rest
    if rest and rest[0] in choices:
        order=rest[0]; color_args=rest[1:]
    elif rest and rest[0] in FORMAT_TYPES and rest[0] not in choices:
        pass
    colors=parse_colors_or_exit(color_args)
    if unique:
        seen=set(); tmp=[]
        for c in colors:
            rb=c.rgb_bytes()
            if rb not in seen:
                seen.add(rb); tmp.append(c)
        colors=tmp
    if order=='random':
        random.shuffle(colors)
    else:
        def key(c):
            if order=='brightness': return (c.brightness(),)+c.rgb_bytes()
            if order=='luminance': return (c.luminance(),)+c.rgb_bytes()
            if order=='chroma': return (c.lch()[1], c.luminance())
            L,C,H=c.lch(); return (H if C>1e-9 else -1, L, C)
        colors=sorted(colors, key=key, reverse=reverse)
    print_hsl_colors(colors)

def command_list(args):
    order='hue'; i=0
    while i < len(args):
        a=args[i]
        if a in ('-s','--sort') or a.startswith('--sort='):
            val,i2=parse_option_value(args,i); order=val; i=i2; continue
        i+=1
    choices=['brightness','luminance','hue','chroma','random']
    if order not in choices: invalid_value(order, '--sort <sort-order>', choices)
    if order=='hue':
        names=HUE_LIST[:]
    elif order=='random':
        names=ALL_NAMES[:]
        random.shuffle(names)
    else:
        def col(n): return parse_color(CSS_HEX[n])
        def key(n):
            c=col(n)
            if order=='brightness': return (c.brightness(),)
            if order=='luminance': return (c.luminance(),)
            if order=='chroma': return (c.lch()[1], c.luminance())
        names=sorted(CANONICAL_NAMES, key=key)
    for n in names:
        print(n)

def command_colorblind(args):
    if not args: required_error('<type>','colorblind')
    typ=args[0]
    if typ not in ('prot','deuter','trit'):
        invalid_value(typ, '<type>', ['prot','deuter','trit'])
    colors=parse_colors_or_exit(args[1:])
    # Matrices fitted to pastel's observed full-deficiency primary simulations in linear RGB.
    mats={
        'prot': [[0.20863687014525575, 1.0, 0.0], [0.1589608350608804, 0.799102738014409, 0.00121410793419535], [0.0, 0.005605391624202723, 1.0]],
        'deuter': [[0.386429433787049, 0.7835377915261935, 0.0], [0.3049873140698863, 0.6104955708078648, 0.0024282158683907], [0.0, 0.033104766570885055, 1.0]],
        'trit': [[1.255528, -0.076749, -0.178779], [-0.078411, 0.930809, 0.147602], [0.004733, 0.691367, 0.303900]],
    }
    out=[]; M=mats[typ]
    for c in colors:
        v=[srgb_to_linear(c.r), srgb_to_linear(c.g), srgb_to_linear(c.b)]
        o=[sum(M[i][j]*v[j] for j in range(3)) for i in range(3)]
        out.append(Color(linear_to_srgb(o[0]),linear_to_srgb(o[1]),linear_to_srgb(o[2]),c.a))
    print_hsl_colors(out)

def command_paint(args, mode):
    bg=None; bold=False; italic=False; underline=False; newline=True; rest=[]; i=0
    while i < len(args):
        a=args[i]
        if a in ('-o','--on'):
            bg=args[i+1] if i+1<len(args) else ''; i+=2; continue
        if a=='--on=' or a.startswith('--on='):
            bg=a.split('=',1)[1]; i+=1; continue
        if a in ('-b','--bold'): bold=True; i+=1; continue
        if a in ('-i','--italic'): italic=True; i+=1; continue
        if a in ('-u','--underline'): underline=True; i+=1; continue
        if a in ('-n','--no-newline'): newline=False; i+=1; continue
        rest.append(a); i+=1
    if not rest: required_error('<color>','paint')
    reader=ColorReader()
    color_s = reader.read_one() if rest[0]=='-' else rest[0]
    try: fg=parse_color(color_s)
    except ValueError:
        sys.stderr.write(f"[pastel error]: Could not parse color '{color_s}'\n"); sys.exit(1)
    bgc=None
    if bg is not None:
        bg_s=reader.read_one() if bg=='-' else bg
        try: bgc=parse_color(bg_s)
        except ValueError:
            sys.stderr.write(f"[pastel error]: Could not parse color '{bg_s}'\n"); sys.exit(1)
    text=' '.join(rest[1:]) if len(rest)>1 else reader.stdin.read()
    use_color = not (mode=='off' or (mode=='auto' and not sys.stdout.isatty()))
    if use_color:
        codes=[]; r,g,b=fg.rgb_bytes()
        if mode=='8bit': codes.append(f"38;5;{ansi8_value(fg)}")
        else: codes.append(f"38;2;{r};{g};{b}")
        if bgc is not None:
            r,g,b=bgc.rgb_bytes()
            if mode=='8bit': codes.append(f"48;5;{ansi8_value(bgc)}")
            else: codes.append(f"48;2;{r};{g};{b}")
        if bold: codes.append('1')
        if italic: codes.append('3')
        if underline: codes.append('4')
        sys.stdout.write('\033['+';'.join(codes)+'m'+text+'\033[0m')
    else:
        sys.stdout.write(text)
    if newline: sys.stdout.write('\n')

def command_pick(args):
    # Print a simple uncolored panel matching the non-tty fallback shape, then the no-picker error.
    print(' ' * 52)
    for _ in range(25):
        print('   ' + '▀'*48 + ' ')
    sys.stderr.write("[pastel error]: Could not find any external color picker tool. See 'pastel pick --help' for more information.\n")
    sys.exit(1)

def command_colorcheck(args):
    # A compact true-color/8-bit checker. The original output is decorative ANSI art; this preserves the visible contract.
    blocks=[(73,39,50),(16,51,30),(29,54,90)]
    print('\n8-bit mode:')
    for _ in range(4):
        line='  '
        for r,g,b in blocks:
            idx=ansi8_value(Color(r/255,g/255,b/255))
            line += f"\033[38;5;{idx};48;5;{idx}m "*8 + '\033[0m  '
        print(line.rstrip())
    print('\n24-bit mode:')
    for _ in range(4):
        line='  '
        for r,g,b in blocks:
            line += f"\033[38;2;{r};{g};{b};48;2;{r};{g};{b}m "*8 + '\033[0m  '
        print(line.rstrip())

