    if cmd=='sort-by': return f"Sort a list of colors by the given property.\n\nExample:\n  pastel random -n 20 | pastel sort-by hue | pastel format hex\n\nUsage: {prog} sort-by [OPTIONS] [sort-order] [color]...\n"
    return None

def invalid_value(val, target, choices):
    sys.stderr.write(f"error: invalid value '{val}' for '{target}'\n  [possible values: {', '.join(choices)}]\n\nFor more information, try '--help'.\n")
    sys.exit(2)

def required_error(arg, cmd):
    sys.stderr.write(f"error: the following required arguments were not provided:\n  {arg}\n\nUsage: {os.path.basename(sys.argv[0])} {cmd} {arg}\n\nFor more information, try '--help'.\n")
    sys.exit(2)

def unknown_arg(arg, usage_cmd=None):
    prog=os.path.basename(sys.argv[0])
    usage=f"{prog} [OPTIONS] <COMMAND>" if usage_cmd is None else f"{prog} {usage_cmd}"
    sys.stderr.write(f"error: unexpected argument '{arg}' found\n\nUsage: {usage}\n\nFor more information, try '--help'.\n")
    sys.exit(2)

