            mode=val; continue
        if a in ('--color-picker',) or a.startswith('--color-picker='):
            val,i2=parse_option_value(args,i); i=i2
            vals=['gpick','xcolor','wcolor','grabc','colorpicker','chameleon','kcolorchooser','zenity','yad','hyprpicker','gdbus']
            if val not in vals: invalid_value(val, '--color-picker <color-picker>', vals)
