    cmd=args[0]; rest=args[1:]
    commands={'color','colorblind','colorcheck','complement','darken','desaturate','distinct','format','gradient','gray','help','lighten','list','mix','paint','pick','random','rotate','saturate','set','sort-by','textcolor','to-gray'}
    if cmd == 'help':
        if not rest:
